{"code": "
import asyncio

async def call_with_retry(func, *args, max_retries=3, delay=3, **kwargs):
    """Call a nethack function with retry on timeout."""
    for attempt in range(max_retries):
        try:
            result = await func(*args, **kwargs)
            return result
        except Exception as e:
            if attempt < max_retries - 1:
                print(f"Attempt {attempt+1} failed: {type(e).__name__}. Retrying in {delay}s...")
                await asyncio.sleep(delay)
            else:
                raise
    return None

# Test it
result = await call_with_retry(nethack.np_look)
print(result)
"}

