async def safe_move(x, y, max_attempts=4):
    """Move to (x,y) with timeout recovery."""
    for attempt in range(max_attempts):
        try:
            result = await nethack.np_move_to(x=x, y=y)
            return result
        except Exception as e:
            print(f"  Attempt {attempt+1} timeout. Trying to recover...")
            await asyncio.sleep(3)
            # Try pressing SPACE/ENTER to clear any stuck prompt
            for key in ["SPACE", "ENTER", "SPACE"]:
                try:
                    await asyncio.sleep(1)
                    r = await nethack.np_press_key(key=key)
                    print(f"  Pressed {key}: {r[:200] if isinstance(r, str) else 'ok'}")
                    # If we got a map back, check if we're at the destination
                    if isinstance(r, str) and "=== MAP ===" in r:
                        return r
                    break  # If press_key worked, try move again
                except:
                    continue
    return "Failed to move after all attempts"

# Let's try to get current state first
try:
    result = await nethack.np_press_key(key="SPACE")
    print(result[:500])
except:
    print("Still stuck")
"}

