import httpx
import json

async def mcp_call(tool_name, arguments=None, timeout=120):
    """Make a direct MCP tool call, bypassing the MCP client library."""
    url = "http://127.0.0.1:37495/mcp"
    token = os.environ.get("NETHACK_MCP_TOKEN", "")

    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream"
    }

    async with httpx.AsyncClient(timeout=timeout) as client:
        # Initialize
        init_request = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "agent", "version": "1.0"}
            }
        }
        resp = await client.post(url, json=init_request, headers=headers)

        # Copy session headers
        for k, v in resp.headers.items():
            if k.lower() not in ['content-length', 'content-type', 'date', 'server']:
                headers[k] = v

        # Call tool
        call_request = {
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/call",
            "params": {
                "name": tool_name,
                "arguments": arguments or {}
            }
        }

        resp2 = await client.post(url, json=call_request, headers=headers)
        data = resp2.json()

        if "result" in data and "content" in data["result"]:
            for item in data["result"]["content"]:
                if item.get("type") == "text":
                    return item["text"]
        elif "error" in data:
            return f"ERROR: {json.dumps(data['error'])}"
        return json.dumps(data)

# Test it
result = await mcp_call("np_look")
print(result)
"}

