import os, json, glob

# Check common locations for settings
paths = [
    os.path.expanduser("~/.prime/settings.json"),
    os.path.expanduser("~/.prime/agent/settings.json"),
    "/tmp/541dc1c66ef94605a6f8827eeeb3c11d/settings.json",
]

# Also search for settings.json files
for p in glob.glob("/tmp/**/settings.json", recursive=True):
    paths.append(p)

for p in paths:
    if os.path.exists(p):
        try:
            with open(p) as f:
                data = json.load(f)
            if 'mcpServers' in str(data) or 'nethack' in str(data):
                print(f"Found config at {p}")
                # Extract nethack URL if present
                if isinstance(data, dict) and 'mcpServers' in data:
                    for k, v in data['mcpServers'].items():
                        if 'nethack' in k.lower() or 'nethack' in str(v).lower():
                            print(f"  {k}: {v}")
                elif isinstance(data, dict):
                    print(f"  Keys: {list(data.keys())}")
                    for k, v in data.items():
                        if 'nethack' in str(v).lower() or 'url' in k.lower() or 'mcp' in k.lower():
                            print(f"  {k}: {v}")
        except:
            pass
"}

