# Let me find a running nethack_v1 process from the SPARSE_ONDEMAND__vison variant
# by checking process environments
import subprocess, json, os

# Get all nethack_v1 process PIDs
result = subprocess.run(["pgrep", "-f", "nethack_v1"], capture_output=True, text=True)
pids = [int(p) for p in result.stdout.strip().split('\n') if p]
print(f"Found {len(pids)} nethack_v1 processes")

# Check each for SPARSE_ONDEMAND variant
for pid in pids:
    try:
        with open(f"/proc/{pid}/environ", 'rb') as f:
            environ = f.read().decode('utf-8', errors='replace')
        if 'SPARSE_ONDEMAND' in environ and 'vison' in environ:
            print(f"\nPID {pid}: SPARSE_ONDEMAND__vison")
            # Extract VF_CONFIG
            for var in environ.split('\0'):
                if var.startswith('VF_CONFIG='):
                    config = json.loads(var[len('VF_CONFIG='):])
                    print(f"  VF_CONFIG: {json.dumps(config, indent=2)}")
                    break
            for var in environ.split('\0'):
                if var.startswith('MCP_PORT_FILE='):
                    print(f"  MCP_PORT_FILE: {var[len('MCP_PORT_FILE='):]}")
                    break
            break
    except:
        pass
