{"code": "
# Efficient descent: explore once if needed, then go to stairs and descend
async def descend_level():
    """Find and go down stairs on current level."""
    # Reveal to find stairs
    map_result = await nethack.reveal(x1=0, y1=0, x2=78, y2=20)
    grid = {}
    for line in map_result.split('\n'):
        if line.startswith('y') and ':' in line:
            parts = line.split(': ', 1)
            y = int(parts[0].replace('y','').strip())
            content = parts[1] if len(parts) > 1 else ''
            for x, ch in enumerate(content):
                if ch != ' ':
                    grid[(x, y)] = ch

    stairs = [(x,y) for (x,y),ch in grid.items() if ch == '>']
    if not stairs:
        print("No stairs found!")
        return False

    sx, sy = stairs[0]

    # Try to move directly
    obs = await nethack.np_move_to(x=sx, y=sy)

    # Check if we reached it
    for line in obs.split('\n'):
        if 'Reached' in line:
            # Go down
            await nethack.np_down()
            return True
        if 'No valid path' in line:
            # Need to explore first
            break
        if 'Interrupting' in line:
            # Made progress but interrupted - try again
            break

    # Try again (handles both "no path" and "interrupted" cases)
    obs = await nethack.np_move_to(x=sx, y=sy)
    for line in obs.split('\n'):
        if 'Reached' in line:
            await nethack.np_down()
            return True

    # If still no luck, explore and try again
    try:
        await nethack.np_explore_level()
    except:
        pass

    obs = await nethack.np_move_to(x=sx, y=sy)
    for line in obs.split('\n'):
        if 'Reached' in line:
            await nethack.np_down()
            return True

    # Last resort: try again
    obs = await nethack.np_move_to(x=sx, y=sy)
    for line in obs.split('\n'):
        if 'Reached' in line:
            await nethack.np_down()
            return True

    return False

# Try to descend from level 1
success = await descend_level()
print(f"Descended: {success}")

# Check status
obs = await nethack.np_look()
for line in obs.split('\n'):
    if 'Dlvl:' in line:
        print(line)
"}

