import json

# Look for the auth file
import os
auth_paths = [
    os.path.expanduser("~/.prime/auth.json"),
    os.path.expanduser("~/.config/prime-agent/auth.json"),
]
for p in auth_paths:
    if os.path.exists(p):
        with open(p) as f:
            auth = json.load(f)
        for key, val in auth.items():
            if "nethack" in key.lower():
                print(f"{key}: {json.dumps(val, indent=2)[:200]}")
"}

